mapper.select:
SELECT A.homepage_id, A.consultings_idx, A.start_date, A.start_time, A.end_date, A.end_time,A.apply_start_date, A.apply_start_time, A.apply_end_date, A.apply_end_time, A.max_apply, A.add_date, A.date_type, (SELECT code_name FROM CMS_CODE B WHERE B.homepage_id = A.homepage_id AND B.code_id = A.date_type AND B.group_id = 'CO001') AS code_name, (SELECT COUNT(*) FROM CMS_CALENDAR_MANAGE B WHERE A.homepage_id = B.homepage_id AND A.homepage_id = #{homepage_id} AND B.date_type = '1' AND B.delete_yn = 'N' AND A.start_date <= B.end_date AND A.end_date >= B.start_date) AS closed_day, (SELECT COUNT(*) FROM CMS_CONSULTINGS_APPLY C WHERE A.homepage_id = C.homepage_id AND A.homepage_id = #{homepage_id} AND A.consultings_idx = C.consultings_idx) AS apply_count, CASE WHEN A.apply_start_date IS NULL THEN apply_yn WHEN SYSDATE BETWEEN TO_DATE(A.apply_start_date || ' ' || A.apply_start_time, 'yyyy-MM-dd HH24:mi') AND TO_DATE(A.apply_end_date || ' ' || A.apply_end_time, 'yyyy-MM-dd HH24:mi') THEN 'Y' ELSE 'N' END AS apply_yn FROM CMS_CONSULTINGS A WHERE 1=1 AND A.homepage_id = #{homepage_id}
AND A.date_type = #{date_type}
AND ( SUBSTR(A.start_date,1,7) = #{plan_date} OR SUBSTR(A.end_date,1,7) = #{plan_date} )

